<?php

declare(strict_types=1);

namespace App\Modules\Billing\Http\Requests;

use App\Modules\Billing\Data\Currency;
use App\Modules\Expenses\Data\ExpenseCategory;
use Carbon\CarbonImmutable;

/**
 * "Add expense". idempotency_key is generated by the form each time it opens,
 * so a double submit records one expense.
 */
final class RecordExpenseRequest extends ExpenseDetailsRequest
{
    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            ...parent::rules(),
            'idempotency_key' => ['required', 'string', 'uuid'],
            'expense_date' => ['required', 'date_format:Y-m-d', 'after_or_equal:2000-01-01', 'before_or_equal:'.CarbonImmutable::now($this->workspace()->timezone)->toDateString()],
        ];
    }

    /**
     * @return array<string, string>
     */
    public function messages(): array
    {
        return ['expense_date.before_or_equal' => 'The expense date cannot be in the future. Use a monthly expense for upcoming costs.'];
    }

    /**
     * @return array{category: ExpenseCategory, description: string, vendor: ?string, amount_minor: int, currency: Currency, expense_date: CarbonImmutable, client_id: ?int, project_id: ?int, notes: ?string}
     */
    public function expense(): array
    {
        return [...$this->details(), 'expense_date' => $this->dateField('expense_date')];
    }
}
